{-| @Backend.Runtime.Kernel.Verify — RSA and P-256 ECDSA signature checks over SHA-256. -}
module Pudu.Backend.Runtime.Kernel.Verify (verifyKernelParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
verifyKernelParts :: [(Text, [Text], [Text])]
verifyKernelParts =
  [ ("verify_rsa", ["sha256", "nat_load", "nat_compare", "nat_mul", "nat_rem", "memory_failure"],
      [ "/* RSASSA-PKCS1-v1_5 over SHA-256: the signature raised to the exponent,"
      , "   modulo the modulus, must be the padded digest at the modulus's byte length. */"
      , "static int pudu_verify_rsa(pudu_box *modulus_bytes, pudu_box *exponent_bytes, pudu_box *message, pudu_box *signature) {"
      , "  static const unsigned char prefix[19] = {0x30, 0x31, 0x30, 0x0d, 0x06, 0x09, 0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x02, 0x01, 0x05, 0x00, 0x04, 0x20};"
      , "  pudu_text modulus = modulus_bytes->fields[0].text, exponent = exponent_bytes->fields[0].text, signed_bytes = signature->fields[0].text;"
      , "  size_t size = modulus.length, count = (size + 3) / 4, signed_count = (signed_bytes.length + 3) / 4 + 1, used;"
      , "  uint32_t *n, *base, *power, *wide, *work, *raw, *expected;"
      , "  pudu_sha256 hash;"
      , "  unsigned char digest[32];"
      , "  int started = 0, same = 0;"
      , "  if (size < 62 || exponent.length == 0) return 0;"
      , "  if (size > SIZE_MAX / 64 || signed_bytes.length > SIZE_MAX / 64) pudu_memory_failure();"
      , "  n = malloc((count * 9 + signed_count * 2 + 8) * sizeof *n);"
      , "  if (n == NULL) pudu_memory_failure();"
      , "  base = n + count;"
      , "  power = base + count;"
      , "  expected = power + count;"
      , "  wide = expected + count;"
      , "  work = wide + 2 * count;"
      , "  raw = work + 3 * count + signed_count + 2;"
      , "  (void)pudu_nat_load(modulus.bytes, size, n, count);"
      , "  for (used = count; used != 0 && n[used - 1] == 0;) used -= 1;"
      , "  for (size_t i = 0; i < exponent.length; ++i) same |= exponent.bytes[i];"
      , "  if (used == 0 || same == 0) { free(n); return 0; }"
      , "  (void)pudu_nat_load(signed_bytes.bytes, signed_bytes.length, raw, signed_count);"
      , "  for (size_t i = 0; i < count; ++i) base[i] = power[i] = 0;"
      , "  pudu_nat_rem(raw, signed_count, n, used, base, work);"
      , "  /* Square and multiply from the exponent's highest set bit. */"
      , "  for (size_t i = 0; i < exponent.length; ++i)"
      , "    for (int bit = 7; bit >= 0; --bit) {"
      , "      int set = (exponent.bytes[i] >> bit) & 1;"
      , "      if (!started) {"
      , "        if (!set) continue;"
      , "        started = 1;"
      , "        memcpy(power, base, used * sizeof *power);"
      , "        continue;"
      , "      }"
      , "      pudu_nat_mul(power, used, power, used, wide);"
      , "      pudu_nat_rem(wide, 2 * used, n, used, power, work);"
      , "      if (set) {"
      , "        pudu_nat_mul(power, used, base, used, wide);"
      , "        pudu_nat_rem(wide, 2 * used, n, used, power, work);"
      , "      }"
      , "    }"
      , "  pudu_sha256_start(&hash);"
      , "  pudu_sha256_feed(&hash, message->fields[0].text.bytes, message->fields[0].text.length);"
      , "  pudu_sha256_finish(&hash, digest);"
      , "  /* 00 01 FF.. 00, the digest's encoding prefix, the digest: as limbs. */"
      , "  for (size_t i = 0; i < count; ++i) expected[i] = 0;"
      , "  for (size_t at = 0; at < size; ++at) {"
      , "    size_t place = size - 1 - at;"
      , "    unsigned char byte = at == 0 ? 0 : at == 1 ? 1 : at < size - 52 ? 0xFF : at == size - 52 ? 0"
      , "      : at < size - 32 ? prefix[at - (size - 51)] : digest[at - (size - 32)];"
      , "    expected[place / 4] |= (uint32_t)byte << (8 * (place % 4));"
      , "  }"
      , "  same = pudu_nat_compare(power, expected, count) == 0;"
      , "  free(n);"
      , "  return same;"
      , "}"
      ])
  , ("p256", ["nat_mul", "nat_rem", "nat_compare"],
      [ "/* Arithmetic on eight-limb values modulo an eight-limb prime, and a point"
      , "   that remembers coordinates written at or above the prime. */"
      , "typedef struct { uint32_t x[8], y[8]; int none; const unsigned char *raw_x, *raw_y; size_t raw_x_length, raw_y_length; } pudu_p256_point;"
      , "static const uint32_t pudu_p256_p[8] = {UINT32_C(0xFFFFFFFF), UINT32_C(0xFFFFFFFF), UINT32_C(0xFFFFFFFF), 0, 0, 0, 1, UINT32_C(0xFFFFFFFF)};"
      , "static const uint32_t pudu_p256_n[8] = {UINT32_C(0xFC632551), UINT32_C(0xF3B9CAC2), UINT32_C(0xA7179E84), UINT32_C(0xBCE6FAAD), UINT32_C(0xFFFFFFFF), UINT32_C(0xFFFFFFFF), 0, UINT32_C(0xFFFFFFFF)};"
      , "static void pudu_p256_mul(const uint32_t *a, const uint32_t *b, const uint32_t *modulus, uint32_t *out) {"
      , "  uint32_t wide[16], work[26];"
      , "  pudu_nat_mul(a, 8, b, 8, wide);"
      , "  pudu_nat_rem(wide, 16, modulus, 8, out, work);"
      , "}"
      , "static void pudu_p256_add(const uint32_t *a, const uint32_t *b, const uint32_t *modulus, uint32_t *out) {"
      , "  uint32_t sum[9], work[19];"
      , "  uint64_t carry = 0;"
      , "  for (int i = 0; i < 8; ++i) { carry += (uint64_t)a[i] + b[i]; sum[i] = (uint32_t)carry; carry >>= 32; }"
      , "  sum[8] = (uint32_t)carry;"
      , "  pudu_nat_rem(sum, 9, modulus, 8, out, work);"
      , "}"
      , "/* a minus b for reduced operands. */"
      , "static void pudu_p256_sub(const uint32_t *a, const uint32_t *b, const uint32_t *modulus, uint32_t *out) {"
      , "  uint32_t turned[8];"
      , "  uint64_t borrow = 0;"
      , "  for (int i = 0; i < 8; ++i) {"
      , "    uint64_t taken = (uint64_t)modulus[i] - b[i] - borrow;"
      , "    turned[i] = (uint32_t)taken;"
      , "    borrow = (taken >> 32) & 1;"
      , "  }"
      , "  pudu_p256_add(a, turned, modulus, out);"
      , "}"
      , "/* The inverse of a non-zero value: its power modulus minus two. */"
      , "static void pudu_p256_invert(const uint32_t *a, const uint32_t *modulus, uint32_t *out) {"
      , "  uint32_t power[8] = {1}, exponent[8];"
      , "  memcpy(exponent, modulus, sizeof exponent);"
      , "  exponent[0] -= 2;"
      , "  for (int bit = 255; bit >= 0; --bit) {"
      , "    pudu_p256_mul(power, power, modulus, power);"
      , "    if (((exponent[bit / 32] >> (bit % 32)) & 1) != 0) pudu_p256_mul(power, a, modulus, power);"
      , "  }"
      , "  memcpy(out, power, sizeof power);"
      , "}"
      , "static int pudu_p256_zero(const uint32_t *a) {"
      , "  uint32_t any = 0;"
      , "  for (int i = 0; i < 8; ++i) any |= a[i];"
      , "  return any == 0;"
      , "}"
      ])
  , ("p256_curve", ["p256", "nat_load", "memory_failure"],
      [ "/* Whether big-endian bytes spell the eight-limb value. */"
      , "static int pudu_p256_spells(const unsigned char *bytes, size_t length, const uint32_t *value) {"
      , "  uint32_t loaded[8];"
      , "  return pudu_nat_load(bytes, length, loaded, 8) && pudu_nat_compare(loaded, value, 8) == 0;"
      , "}"
      , "/* Big-endian bytes of any length, reduced. */"
      , "static void pudu_p256_reduce(const unsigned char *bytes, size_t length, const uint32_t *modulus, uint32_t *out) {"
      , "  size_t count = (length + 3) / 4 + 8;"
      , "  uint32_t *limbs;"
      , "  if (length > SIZE_MAX / 64) pudu_memory_failure();"
      , "  limbs = malloc((2 * count + 10) * sizeof *limbs);"
      , "  if (limbs == NULL) pudu_memory_failure();"
      , "  (void)pudu_nat_load(bytes, length, limbs, count);"
      , "  pudu_nat_rem(limbs, count, modulus, 8, out, limbs + count);"
      , "  free(limbs);"
      , "}"
      , "/* Equality of two points as written: a point given with a coordinate at or"
      , "   above the prime equals only itself. */"
      , "static int pudu_p256_same(const pudu_p256_point *a, const pudu_p256_point *b) {"
      , "  if (a->raw_x != NULL && b->raw_x != NULL) return 1;"
      , "  if (a->raw_x != NULL) return pudu_p256_spells(a->raw_x, a->raw_x_length, b->x) && pudu_p256_spells(a->raw_y, a->raw_y_length, b->y);"
      , "  if (b->raw_x != NULL) return pudu_p256_spells(b->raw_x, b->raw_x_length, a->x) && pudu_p256_spells(b->raw_y, b->raw_y_length, a->y);"
      , "  return pudu_nat_compare(a->x, b->x, 8) == 0 && pudu_nat_compare(a->y, b->y, 8) == 0;"
      , "}"
      , "/* Whether a is b with its y taken from the prime, again as written. */"
      , "static int pudu_p256_opposite(const pudu_p256_point *a, const pudu_p256_point *b) {"
      , "  const pudu_p256_point *plain = a->raw_x != NULL ? b : a, *other = a->raw_x != NULL ? a : b;"
      , "  uint32_t turned[8];"
      , "  uint64_t borrow = 0;"
      , "  if (a->raw_x != NULL && b->raw_x != NULL) return 0;"
      , "  for (int i = 0; i < 8; ++i) {"
      , "    uint64_t taken = (uint64_t)pudu_p256_p[i] - plain->y[i] - borrow;"
      , "    turned[i] = (uint32_t)taken;"
      , "    borrow = (taken >> 32) & 1;"
      , "  }"
      , "  if (other->raw_x != NULL) return pudu_p256_spells(other->raw_x, other->raw_x_length, plain->x) && pudu_p256_spells(other->raw_y, other->raw_y_length, turned);"
      , "  return pudu_nat_compare(other->x, plain->x, 8) == 0 && pudu_nat_compare(other->y, turned, 8) == 0;"
      , "}"
      , "/* The tangent rule; no point when twice y has no inverse. */"
      , "static void pudu_p256_double(const pudu_p256_point *p, pudu_p256_point *out) {"
      , "  static const uint32_t three[8] = {3};"
      , "  const uint32_t *m = pudu_p256_p;"
      , "  uint32_t slope[8], top[8], bottom[8], x[8], y[8];"
      , "  pudu_p256_point made = {{0}, {0}, 1, NULL, NULL, 0, 0};"
      , "  if (!p->none) {"
      , "    pudu_p256_add(p->y, p->y, m, bottom);"
      , "    if (!pudu_p256_zero(bottom)) {"
      , "      pudu_p256_mul(p->x, p->x, m, top);"
      , "      pudu_p256_mul(top, three, m, top);"
      , "      pudu_p256_sub(top, three, m, top);"
      , "      pudu_p256_invert(bottom, m, bottom);"
      , "      pudu_p256_mul(top, bottom, m, slope);"
      , "      pudu_p256_mul(slope, slope, m, x);"
      , "      pudu_p256_sub(x, p->x, m, x);"
      , "      pudu_p256_sub(x, p->x, m, x);"
      , "      pudu_p256_sub(p->x, x, m, y);"
      , "      pudu_p256_mul(slope, y, m, y);"
      , "      pudu_p256_sub(y, p->y, m, y);"
      , "      made.none = 0;"
      , "      memcpy(made.x, x, sizeof x);"
      , "      memcpy(made.y, y, sizeof y);"
      , "    }"
      , "  }"
      , "  *out = made;"
      , "}"
      , "/* The chord rule, with the reference's cases in its order. */"
      , "static void pudu_p256_join(const pudu_p256_point *p, const pudu_p256_point *q, pudu_p256_point *out) {"
      , "  const uint32_t *m = pudu_p256_p;"
      , "  uint32_t slope[8], top[8], bottom[8], x[8], y[8];"
      , "  pudu_p256_point made = {{0}, {0}, 1, NULL, NULL, 0, 0};"
      , "  if (p->none) { made = *q; *out = made; return; }"
      , "  if (q->none) { made = *p; *out = made; return; }"
      , "  if (pudu_p256_same(p, q)) { pudu_p256_double(p, out); return; }"
      , "  if (!pudu_p256_opposite(p, q)) {"
      , "    pudu_p256_sub(p->x, q->x, m, bottom);"
      , "    if (!pudu_p256_zero(bottom)) {"
      , "      pudu_p256_sub(p->y, q->y, m, top);"
      , "      pudu_p256_invert(bottom, m, bottom);"
      , "      pudu_p256_mul(top, bottom, m, slope);"
      , "      pudu_p256_mul(slope, slope, m, x);"
      , "      pudu_p256_sub(x, p->x, m, x);"
      , "      pudu_p256_sub(x, q->x, m, x);"
      , "      pudu_p256_sub(p->x, x, m, y);"
      , "      pudu_p256_mul(slope, y, m, y);"
      , "      pudu_p256_sub(y, p->y, m, y);"
      , "      made.none = 0;"
      , "      memcpy(made.x, x, sizeof x);"
      , "      memcpy(made.y, y, sizeof y);"
      , "    }"
      , "  }"
      , "  *out = made;"
      , "}"
      ])
  , ("verify_ecdsa", ["p256_curve", "sha256"],
      [ "/* ECDSA over P-256 with SHA-256 and a 64-byte signature. The public point"
      , "   is used as given, without a curve check, as the reference uses it. */"
      , "static int pudu_verify_ecdsa(pudu_box *x_bytes, pudu_box *y_bytes, pudu_box *message, pudu_box *signature) {"
      , "  static const uint32_t base_x[8] = {UINT32_C(0xD898C296), UINT32_C(0xF4A13945), UINT32_C(0x2DEB33A0), UINT32_C(0x77037D81), UINT32_C(0x63A440F2), UINT32_C(0xF8BCE6E5), UINT32_C(0xE12C4247), UINT32_C(0x6B17D1F2)};"
      , "  static const uint32_t base_y[8] = {UINT32_C(0x37BF51F5), UINT32_C(0xCBB64068), UINT32_C(0x6B315ECE), UINT32_C(0x2BCE3357), UINT32_C(0x7C0F9E16), UINT32_C(0x8EE7EB4A), UINT32_C(0xFE1A7F9B), UINT32_C(0x4FE342E2)};"
      , "  pudu_text x = x_bytes->fields[0].text, y = y_bytes->fields[0].text, signed_bytes = signature->fields[0].text;"
      , "  uint32_t r[8], s[8], z[8], w[8], first[8], second[8], found[8], work[19];"
      , "  pudu_p256_point base = {{0}, {0}, 0, NULL, NULL, 0, 0}, given = base, both, held = {{0}, {0}, 1, NULL, NULL, 0, 0};"
      , "  pudu_sha256 hash;"
      , "  unsigned char digest[32];"
      , "  if (signed_bytes.length != 64 || x.length == 0 || y.length == 0) return 0;"
      , "  (void)pudu_nat_load(signed_bytes.bytes, 32, r, 8);"
      , "  (void)pudu_nat_load(signed_bytes.bytes + 32, 32, s, 8);"
      , "  if (pudu_p256_zero(r) || pudu_p256_zero(s) || pudu_nat_compare(r, pudu_p256_n, 8) >= 0 || pudu_nat_compare(s, pudu_p256_n, 8) >= 0) return 0;"
      , "  pudu_sha256_start(&hash);"
      , "  pudu_sha256_feed(&hash, message->fields[0].text.bytes, message->fields[0].text.length);"
      , "  pudu_sha256_finish(&hash, digest);"
      , "  (void)pudu_nat_load(digest, 32, z, 8);"
      , "  pudu_p256_invert(s, pudu_p256_n, w);"
      , "  pudu_p256_mul(z, w, pudu_p256_n, first);"
      , "  pudu_p256_mul(r, w, pudu_p256_n, second);"
      , "  memcpy(base.x, base_x, sizeof base_x);"
      , "  memcpy(base.y, base_y, sizeof base_y);"
      , "  pudu_p256_reduce(x.bytes, x.length, pudu_p256_p, given.x);"
      , "  pudu_p256_reduce(y.bytes, y.length, pudu_p256_p, given.y);"
      , "  if (!pudu_p256_spells(x.bytes, x.length, given.x) || !pudu_p256_spells(y.bytes, y.length, given.y)) {"
      , "    given.raw_x = x.bytes;"
      , "    given.raw_x_length = x.length;"
      , "    given.raw_y = y.bytes;"
      , "    given.raw_y_length = y.length;"
      , "  }"
      , "  pudu_p256_join(&base, &given, &both);"
      , "  /* Both scalars at once from their highest bit: double, then add the base,"
      , "     the given point or their sum as the two bits say. */"
      , "  for (int bit = 255; bit >= 0; --bit) {"
      , "    int one = (first[bit / 32] >> (bit % 32)) & 1, two = (second[bit / 32] >> (bit % 32)) & 1;"
      , "    pudu_p256_point doubled;"
      , "    pudu_p256_double(&held, &doubled);"
      , "    held = doubled;"
      , "    if (one || two) {"
      , "      pudu_p256_join(one && two ? &both : one ? &base : &given, &doubled, &held);"
      , "    }"
      , "  }"
      , "  if (held.none) return 0;"
      , "  if (held.raw_x != NULL) pudu_p256_reduce(held.raw_x, held.raw_x_length, pudu_p256_n, found);"
      , "  else pudu_nat_rem(held.x, 8, pudu_p256_n, 8, found, work);"
      , "  return pudu_nat_compare(found, r, 8) == 0;"
      , "}"
      ])
  ]
